<?php
require '../auth.php';require '../../config/koneksi.php';$search=trim($_GET['search']??'');$jenis=trim($_GET['jenis']??'');$allowed=['Keuangan','Kegiatan','Donasi','Pembangunan'];if(!in_array($jenis,$allowed,true))$jenis='';$page=max(1,(int)($_GET['page']??1));$limit=10;$start=($page-1)*$limit;$where='WHERE 1=1';if($search!==''){$safe=mysqli_real_escape_string($conn,$search);$where.=" AND (l.judul_laporan LIKE '%$safe%' OR l.deskripsi LIKE '%$safe%')";}if($jenis!=='')$where.=" AND l.jenis_laporan='".mysqli_real_escape_string($conn,$jenis)."'";$total=(int)(mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) total FROM laporan l $where"))['total']??0);$totalPages=max(1,(int)ceil($total/$limit));$data=mysqli_query($conn,"SELECT l.*,u.nama_lengkap nama_admin FROM laporan l LEFT JOIN users u ON l.created_by=u.id $where ORDER BY l.tanggal DESC,l.id DESC LIMIT $start,$limit");
$page_title='Data Laporan';$active_menu='laporan';$admin_base='..';include '../includes/header.php';
?>
<div class="admin-page-header"><div><h1>Data Laporan</h1><p><?= $total ?> laporan tersimpan</p></div><a class="btn-tambah" href="tambah.php">+ Tambah Laporan</a></div><div class="content-card"><form method="GET" class="filter-bar"><input name="search" value="<?= htmlspecialchars($search,ENT_QUOTES,'UTF-8') ?>" placeholder="Cari laporan..."><select name="jenis"><option value="">Semua Jenis</option><?php foreach($allowed as $item):?><option <?= $jenis===$item?'selected':'' ?>><?= $item ?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="table-responsive"><table><thead><tr><th>Tanggal</th><th>Judul</th><th>Jenis</th><th>Dibuat Oleh</th><th>Aksi</th></tr></thead><tbody><?php if(mysqli_num_rows($data)===0):?><tr><td colspan="5" class="empty">Laporan tidak ditemukan.</td></tr><?php endif;?><?php while($row=mysqli_fetch_assoc($data)):?><tr><td><?= date('d-m-Y',strtotime($row['tanggal'])) ?></td><td><?= htmlspecialchars($row['judul_laporan'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge"><?= htmlspecialchars($row['jenis_laporan'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars($row['nama_admin']??'Admin',ENT_QUOTES,'UTF-8') ?></td><td><a class="btn-detail" href="detail.php?id=<?= (int)$row['id'] ?>">Detail</a> <a class="btn-edit" href="edit.php?id=<?= (int)$row['id'] ?>">Edit</a> <a class="btn-hapus" href="hapus.php?id=<?= (int)$row['id'] ?>" onclick="return confirm('Hapus laporan ini? File lama tetap disimpan.')">Hapus</a></td></tr><?php endwhile;?></tbody></table></div><div class="pagination"><?php for($i=1;$i<=$totalPages;$i++):?><a class="<?= $i===$page?'active-page':'' ?>" href="?page=<?= $i ?>&search=<?= urlencode($search) ?>&jenis=<?= urlencode($jenis) ?>"><?= $i ?></a><?php endfor;?></div></div>
